def count_up_to(n):
    if n <= 2:
        return []

    # Sieve of Eratosthenes to find all primes less than n
    sieve = [True] * n
    sieve[0] = False
    sieve[1] = False

    for i in range(2, int(n**0.5) + 1):
        if sieve[i]:
            for j in range(i*i, n, i):
                sieve[j] = False

    return [i for i, is_prime in enumerate(sieve) if is_prime]
